import type { Manifest } from "../schema.js";

const q = (s: string) => JSON.stringify(s);

/** Renders docker-compose.yml. No host ports are published: access is via the Tailscale sidecar only. */
export function renderCompose(m: Manifest): string {
  const volNames = Object.keys(m.volumes);
  const volumeMounts = volNames.map((v) => `      - ${m.projectName.replace(/-/g, "_")}_${v}:${m.volumes[v].mount}`);

  const lines: string[] = [
    "# GENERATED by sandboxctl from sandbox.config.ts. Do not edit by hand (run `sandboxctl generate`).",
    "services:",
    "  tailscale:",
    "    image: tailscale/tailscale:stable",
    `    container_name: ${m.containerName}_tailscale`,
    `    hostname: ${m.network.tailscaleHostname}`,
    "    restart: unless-stopped",
    "    environment:",
    `      - TS_AUTHKEY=\${${m.network.authKeyEnv}:-}`,
    `      - TS_HOSTNAME=${m.network.tailscaleHostname}`,
    `      - TS_EXTRA_ARGS=--advertise-tags=${m.network.tailscaleTag}`,
    "      - TS_STATE_DIR=/var/lib/tailscale",
    "      - TS_USERSPACE=false",
    "    volumes:",
    `      - ${m.projectName.replace(/-/g, "_")}_tailscale_state:/var/lib/tailscale`,
    "    devices:",
    "      - /dev/net/tun:/dev/net/tun",
    "    cap_add:",
    "      - NET_ADMIN",
    "      - SYS_MODULE",
    "    # NOTE: no `ports:` anywhere. Nothing is published on the Windows host.",
    "",
    "  dev:",
    "    build:",
    "      context: .",
    "      dockerfile: Dockerfile",
    `    container_name: ${m.containerName}`,
    "    restart: unless-stopped",
    "    network_mode: service:tailscale",
    "    depends_on:",
    "      - tailscale",
    "    stdin_open: true",
    "    tty: true",
    "    working_dir: /projects",
    "    cap_add:",
    "      - SYS_PTRACE",
    "    deploy:",
    "      resources:",
    "        reservations:",
    "          devices:",
    "            - driver: nvidia",
    "              count: all",
    "              capabilities: [gpu]",
    "    volumes:",
    ...volumeMounts,
    `      - ${m.paths.buddyEnvFile}:/root/.buddy/.env:ro`,
    `      - ${m.paths.metaDir}/antigravity-data:/root/.gemini`,
    `      - ${m.paths.metaDir}/rules:/root/.gemini/config/rules`,
    `      - ${m.paths.metaDir}/skills:/root/.gemini/config/skills`,
    `      - ${m.paths.metaDir}/tools:/root/.gemini/config/tools`,
    `      - ${m.paths.metaDir}/plugins:/root/.gemini/config/plugins`,
    `      - ..:/opt/the-forge${m.selfRebuild ? "" : ":ro"}`,
    ...(m.selfRebuild ? ["      - /var/run/docker.sock:/var/run/docker.sock"] : []),
    "      - ./entrypoint.sh:/usr/local/bin/entrypoint.sh",
    "      - ./Caddyfile:/etc/caddy/Caddyfile:ro",
    "    environment:",
    "      - NVIDIA_VISIBLE_DEVICES=all",
    "      - NVIDIA_DRIVER_CAPABILITIES=compute,utility",
    "      - DOTNET_CLI_TELEMETRY_OPTOUT=1",
    "      - GH_TOKEN=${GH_TOKEN:-}",
    "      - ANTHROPIC_API_KEY=${ANTHROPIC_API_KEY:-}",
    "      - CLAUDE_CODE_OAUTH_TOKEN=${CLAUDE_CODE_OAUTH_TOKEN:-}",
    `      - OLLAMA_FLASH_ATTENTION=${m.ollama.flashAttention ? 1 : 0}`,
    `      - OLLAMA_KV_CACHE_TYPE=${m.ollama.kvCacheType}`,
    `      - OLLAMA_KEEP_ALIVE=${m.ollama.keepAlive}`,
    `      - OLLAMA_NUM_PARALLEL=${m.ollama.numParallel}`,
    `      - OLLAMA_MODEL=${m.ollama.primaryModel}`,
    `      - OLLAMA_EXTRA_MODELS=${m.ollama.extraModels.join(",")}`,
    "      - TOKEN_SAVER_ENABLED=true",
    "      - IS_SANDBOX=1",
    `      - GIT_MAIN_BRANCH=${m.git.mainBranch}`,
    `      - GIT_INTEGRATION_BRANCH=${m.git.integrationBranch}`,
    "",
    "volumes:",
  ];

  const prefix = m.projectName.replace(/-/g, "_");
  for (const v of [...volNames, "tailscale_state"]) {
    lines.push(`  ${prefix}_${v}:`, `    name: ${prefix}_${v}`);
  }
  return lines.join("\n") + "\n";
}

export { q };
